commands.command:
@'
import { loadPackageFromDirectory } from './packages/core/src/application/package-loader.ts';
import { validatePackage } from './packages/core/src/application/validate-package.ts';
import { NodeFileSystem } from './packages/node/src/file-system.ts';
import { CodexAdapter } from './packages/adapter-codex/src/index.ts';
import { ClaudeCodeAdapter } from './packages/adapter-claude/src/index.ts';
const loaded = await loadPackageFromDirectory(new NodeFileSystem(), 'skills/database-index-design', { strict: true });
const report = validatePackage(loaded.pkg, { directoryName: 'database-index-design', adapters: [new CodexAdapter(), new ClaudeCodeAdapter()] });
const issues = [...loaded.issues, ...report.issues];
console.log(JSON.stringify({name:loaded.pkg.manifest.name,version:loaded.pkg.manifest.version,files:loaded.pkg.files.map(f=>f.path),issues},null,2));
if(issues.length)process.exitCode=1;
'@ | node --input-type=module

@'
import { readFileSync, readdirSync, statSync, existsSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
const root=resolve('skills/database-index-design');
const files=[];
function visit(dir){for(const name of readdirSync(dir)){const p=resolve(dir,name); if(statSync(p).isDirectory())visit(p); else if(p.endsWith('.md'))files.push(p);}}
visit(root);
const links=[];
for(const file of files){const source=readFileSync(file,'utf8');for(const m of source.matchAll(/\[[^\]]+\]\(([^)]+)\)/g)){const target=m[1];if(/^[a-z]+:/i.test(target))continue; const path=resolve(dirname(file),target.split('#')[0]); links.push({file,target,exists:existsSync(path)});}}
console.log(JSON.stringify({markdownFiles:files.length,localLinks:links,missing:links.filter(x=>!x.exists).length},null,2));
if(links.some(x=>!x.exists))process.exitCode=1;
'@ | node --input-type=module

